INSERT INTO event VALUES(10,1,10,'context.blob',1,'["golden-host",1,"process-1"]',1767225610000,'{"payload":{"digest":"7b5c90e6a791e93fcd2dbed85cb2e0c68d68eb9b1f5b4bc0f97ebef6b2107af5","value":"{\"sections\":{\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories are always loaded unless the user forbids memory use. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. When project context, coding patterns, or conventions are relevant to the task and git is available, look into git history (commit messages, PR descriptions, recent changes) to understand them. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\",\"tool-call\":\"When using a tool, follow the JSON schema exactly and include all required properties.\\nAlways produce valid JSON when calling a tool.\\nDo not call tools that are not provided or any multi_tool_use variants.\\nCall tools sequentially and wait for the output before calling another.\"},\"tools\":[\"memory\"]}"}}');
INSERT INTO event VALUES(11,1,11,'context.blob',1,'["golden-host",1,"process-1"]',1767225611000,'{"payload":{"digest":"7c7ddfe43cf2f9e505133e8972afbd8c0077866b9a7f5c91ff960d7c28668345","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"type\":\"string\"},\"insert_line\":{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"new_str\":{\"type\":\"string\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"old_str\":{\"type\":\"string\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted.\"},\"view_range\":{\"anyOf\":[{\"prefixItems\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}],\"type\":\"array\"},{\"type\":\"null\"}]}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
