INSERT INTO event VALUES(27,2,9,'context.blob',1,'["golden-host",2,"process-2"]',1767225627000,'{"payload":{"digest":"5df8e820ff5dfaa7efd8575590087799988dd4625b767dbce10a093e232ca0be","value":"{\"sections\":{\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories are always loaded unless the user forbids memory use. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. When project context, coding patterns, or conventions are relevant to the task and git is available, look into git history (commit messages, PR descriptions, recent changes) to understand them. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\\n<orchestrator_memory_protocol>\\nThe /memories directory is shared with all subagents you launch. Subagents can read and write the same files. Use this for persistent context that should survive across conversations. Do not use it as a substitute for subagent result delivery because subagents report back automatically via follow-up messages. Good uses include project conventions, user preferences, and research bibliographies that build up over time.\\n\\nFor continuation or delegation-heavy work, consult relevant memories instead of rediscovering context. Record reusable intelligence: what approaches worked or failed and why, project structure and conventions you discovered, user preferences revealed through corrections or rejections, and effective problem-solving strategies.\\n</orchestrator_memory_protocol>\",\"tool-call\":\"When using a tool, follow the JSON schema exactly and include all required properties.\\nAlways produce valid JSON when calling a tool.\\nDo not call tools that are not provided or any multi_tool_use variants.\\nCall tools sequentially and wait for the output before calling another.\"},\"tools\":[\"read_file\",\"plan\",\"delegate_multi_agents\",\"delegate_agent\",\"executions\",\"memory\"]}"}}');
INSERT INTO event VALUES(28,2,10,'context.blob',1,'["golden-host",2,"process-2"]',1767225628000,'{"payload":{"digest":"a1516829e616a7b5349733f50c8cc6c84856b87d1bb09660d73e5ab8b051b3a5","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"additionalProperties\":false,\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line to read, inclusive and 1-indexed.\"},\"start\":{\"description\":\"First line to read, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(29,2,11,'context.blob',1,'["golden-host",2,"process-2"]',1767225629000,'{"payload":{"digest":"785513cceb972bc0589bcf87202a9c7d05b923c67f5d40b51e14e6f2ce5ba776","value":"{\"description\":\"Manage the plan document and (optionally) the autonomous goal pursuing it.\\n\\nCommands:\\n- update: Propose or replace the plan. Required field: `objective` - a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every update is presented to the user for approval; they may approve, run the plan as a goal, or reject. Update only when the objective or approach genuinely changes.\\n- pause: Self-pause the goal pursuing this plan when you genuinely need user input to proceed. Required field: `reason` describing what you need.\\n- complete: Mark the goal pursuing this plan complete. Required field: `reason` describing how you verified completion against current external state. Only call this once the objective''s stopping condition is verifiably true.\\n\\npause/complete only affect autonomous goals; with no goal running they return guidance for ordinary chat.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"update\",\"pause\",\"complete\"],\"type\":\"string\"},\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps (track those with the todo tool).\",\"minLength\":1,\"type\":\"string\"},\"reason\":{\"description\":\"Why you are pausing: describe what you need from the user.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
