INSERT INTO event VALUES(33,2,15,'context.blob',1,'["golden-host",2,"process-2"]',1767225633000,'{"payload":{"digest":"7c7ddfe43cf2f9e505133e8972afbd8c0077866b9a7f5c91ff960d7c28668345","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"type\":\"string\"},\"insert_line\":{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"new_str\":{\"type\":\"string\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"old_str\":{\"type\":\"string\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted.\"},\"view_range\":{\"anyOf\":[{\"prefixItems\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}],\"type\":\"array\"},{\"type\":\"null\"}]}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
