INSERT INTO event VALUES(97,5,11,'context.blob',1,'["golden-host",2,"process-2"]',1767225697000,'{"payload":{"digest":"7c7ddfe43cf2f9e505133e8972afbd8c0077866b9a7f5c91ff960d7c28668345","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"type\":\"string\"},\"insert_line\":{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"new_str\":{\"type\":\"string\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"old_str\":{\"type\":\"string\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted.\"},\"view_range\":{\"anyOf\":[{\"prefixItems\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}],\"type\":\"array\"},{\"type\":\"null\"}]}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(98,5,12,'context.blob',1,'["golden-host",2,"process-2"]',1767225698000,'{"payload":{"digest":"785513cceb972bc0589bcf87202a9c7d05b923c67f5d40b51e14e6f2ce5ba776","value":"{\"description\":\"Manage the plan document and (optionally) the autonomous goal pursuing it.\\n\\nCommands:\\n- update: Propose or replace the plan. Required field: `objective` - a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every update is presented to the user for approval; they may approve, run the plan as a goal, or reject. Update only when the objective or approach genuinely changes.\\n- pause: Self-pause the goal pursuing this plan when you genuinely need user input to proceed. Required field: `reason` describing what you need.\\n- complete: Mark the goal pursuing this plan complete. Required field: `reason` describing how you verified completion against current external state. Only call this once the objective''s stopping condition is verifiably true.\\n\\npause/complete only affect autonomous goals; with no goal running they return guidance for ordinary chat.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"update\",\"pause\",\"complete\"],\"type\":\"string\"},\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps (track those with the todo tool).\",\"minLength\":1,\"type\":\"string\"},\"reason\":{\"description\":\"Why you are pausing: describe what you need from the user.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(99,5,13,'context.blob',1,'["golden-host",2,"process-2"]',1767225699000,'{"payload":{"digest":"0ce4c9ac67028d910bc2f2e350476d34f81920c6facc0bc55394b1ac02d42bfb","value":"{\"description\":\"Submit the final result. Call this exactly once, with the complete result, when the task is done.\",\"name\":\"submit_output\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"answer\":{\"type\":\"string\"}},\"required\":[\"answer\"],\"type\":\"object\"}}"}}');
